    total = 0
    for (l, r) in offers:
        if r - l + 1 >= x:
            # check if all days l..r are free
            if all(!occupied[i] for i in range(l, r+1)):
                # mark all days as occupied
                for i in range(l, r+1):
                    occupied[i] = True
                total += r - l + 1
    print(total)
```

