class SegmentTree:
    def __init__(self, n):
        self.n = n
        self.tree = [0] * (4 * n)

    def query(self, node, start, end, l, r):
        """Returns True if all positions in [l, r] are 0 (free)"""
        if r < start or end < l:
            return True
        if l <= start and end <= r:
            return self.tree[node] == 0

        mid = (start + end) // 2
        left_free = self.query(2 * node, start, mid, l, r)
        right_free = self.query(2 * node + 1, mid + 1, end, l, r)
        return left_free and right_free

    def update(self, node, start, end, l, r):
        """Mark all positions in [l, r] as 1 (occupied)"""
        if r < start or end < l:
            return
        if l <= start and end <= r:
            self.tree[node] = sum(end - start + 1)
            return

        mid = (start + end) // 2
        self.update(2 * node, start, mid, l, r)
        self.update(2 * node + 1, mid + 1, end, l, r)
        self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    n, m = map(int, lines[0].split())

    offers = []
    for i in range(1, len(lines)):
        if lines[i]:
            l, r = map(int, lines[i].split())
            offers.append((l, r))

    results = []

    for x in range(1, n + 1):
        st = SegmentTree(n + 2)
        total = 0

