```python
from collections import defaultdict
import sys

class Dinic:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]

    def add_edge(self, u, v, cap):
        self.graph[u].append([v, float('inf'), cap, len(self.graph[v])])
        self.graph[v].append([u, float('inf'), 0, len(self.graph[u]) - 1])

    def bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        q = [s]
        while q:
            u = q.pop(0)
            for v, flow, cap, rev in self.graph[u]:
                if cap > 0 and self.level[v] < 0:
                    self.level[v] = self.level[u] + 1
                    q.append(v)
        return self.level[t] >= 0

    def dfs(self, u, t, pushed, ptr):
        if pushed == 0 or u == t:
            return pushed
        for i in range(ptr[u], len(self.graph[u])):
            ptr[u] = i
            v, flow, cap, rev = self.graph[u][i]
            if self.level[v] != self.level[u] + 1 or cap == 0:
                continue
            tr = self.dfs(v, t, min(pushed, cap), ptr)
            if tr == 0:
                continue
            self.graph[u][i][2] -= tr
            self.graph[v][rev][2] += tr
            return tr
        return 0

    def max_flow(self, s, t):
        flow = 0
        while self.bfs(s, t):
            ptr = [0] * self.n
            while True:
                pushed = self.dfs(s, t, float('inf'), ptr)
                if pushed == 0:
                    break
                flow += pushed
        return flow

def factorize(n):
    factors = defaultdict(int)
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors[d] += 1
            n //= d
        d += 1
    if n > 1:
        factors[n] += 1
    return factors

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    pairs = []
    for i in range(m):
        u, v = map(int, line.split())
        pairs.append((u-1, v-1))  # 0-indexed

    pos_factors = [factorize(x) for x in a]

    ans = 0

    all_primes = set()
    for pf in pos_factors:
        all_primes.update(pf.keys())

    for p in all_primes:
        cnts = [0] * n
        for i in range(n):
            cnts[i] = pos_factors[i].get(p, 0)

        # Build flow network
        source = 0
        sink = n + 1
        dinic = Dinic(n + 2)

        for i in range(n):
            cnt = cnts[i]
            if cnt > 0:
                is_odd = (i + 1) % 2 == 1
                if is_odd:
                    # Odd positions from source
                    dinic.add_edge(source, 1 + i, cnt)
                else:
                    # Even positions to sink
                    dinic.add_edge(1 + i, sink, cnt)

        for u, v in pairs:
            # Both must have the prime for flow to pass (but we use INF capacity and check at pos)
            dinic.add_edge(1 + u, 1 + v, float('inf'))
            dinic.add_edge(1 + v, 1 + u, float('inf'))

        ans += dinic.max_flow(source, sink)

    return str(ans) + '\n'
