Looking at this problem, I need to count squares of two types (axis-aligned and diamond-shaped) in a 0-1 grid. Each square must:
1. Have a frame of 1s (border)
2. Have 0s inside (interior)
3. Not touch any foreign 1s (by side or corner)

Let me write an efficient solution that checks both types of squares:

```python
def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0
    t = int(lines[idx])
    idx += 1

    results = []

    for _ in range(t):
        n, m = map(int, lines[idx].split())
        idx += 1

        grid = lines[idx:idx+n]
        idx += n

        r, c = n, m
        count = 0

        # Check axis-aligned squares
        for size in range(2, min(r, c) + 1):
            for y_start in range(r - size + 1):
                for x_start in range(c - size + 1):
                    is_valid = True

                    # Check border is all 1s
                    for x in range(size):
                        if grid[y_start][x_start + x] != '1':
                            is_valid = False
                            break
                    if not is_valid:
                        continue
                    for x in range(size):
                        if grid[y_start + size - 1][x_start + x] != '1':
                            is_valid = False
                            break
                    if not is_valid:
                        continue
                    for y in range(size):
                        if grid[y_start + y][x_start] != '1':
                            is_valid = False
                            break
                    if not is_valid:
                        continue
                    for y in range(size):
                        if grid[y_start + y][x_start + size - 1] != '1':
                            is_valid = False
                            break
                    if not is_valid:
                        continue

                    # Check interior is all 0s (if any)
                    if size > 2:
                        for y in range(1, y_start + size - 1):
                            for x in range(1, x_start + size - 1):
                                if grid[y][x] != '0':
                                    is_valid = False
                                    break
                            if not is_valid:
                                break
                        if not is_valid:
                            continue
                        # Correct interior range
                        for y in range(y_start + 1, y_start + size - 1):
                            for x in range(x_start + 1, x_start + size - 1):
                                if grid[y][x] != '0':
                                    is_valid = False
                                    break
                            if not is_valid:
                                break

                    if is_valid:
                        # Check no foreign 1s touch the square (exterior check)
                        is_exterior_clean = True
                        for y in range(r):
                            for x in range(c):
                                dist_y = abs(y - y_start)
                                dist_x = abs(x - x_start)
                                if (dist_y == 0 and dist_x >= size) or \
                                   (dist_y == size - 1 and dist_x >= 1) or \
                                   (dist_y >= 1 and dist_y <= 1 and dist_x == size) or \
                                   (dist_y == 1 and dist_x == size - 1):
                                    if grid[y][x] == '1':
                                        is_exterior_clean = False
                                        break
                            if not is_exterior_clean:
                                break

                        if is_exterior_clean:
                            count += 1

        # Check diamond (rotated) squares
        for cy in range(1, r - 1):
            for cx in range(1, c - 1):
                max_radius = min(cy, cx, r - 1 - cy, c - 1 - cx)
                for radius in range(1, max_radius + 1):
                    is_valid = True
                    # Check all boundary cells are 1
                    for y in range(r):
                        for x in range(c):
                            if abs(y - cy) + abs(x - cx) == radius:
                                if grid[y][x] != '1':
                                    is_valid = False
                                    break
                        if not is_valid:
                            break
                    if not is_valid:
                        continue
                    # Check all interior cells are 0
                    for y in range(r):
                        for x in range(c):
                            if abs(y - cy) + abs(x - cx) < radius:
                                if grid[y][x] != '0':
                                    is_valid = False
                                    break
                        if not is_valid:
                            break
                    if not is_valid:
                        continue
                    # Check no foreign 1s touch the diamond (at distance radius+1)
                    is_exterior_clean = True
                    for y in range(r):
                        for x in range(c):
                            dist = abs(y - cy) + abs(x - cx)
                            if dist == radius + 1:
                                if grid[y][x] == '1':
                                    is_exterior_clean = False
                                    break
                            if not is_exterior_clean:
                                break
                    if is_exterior_clean:
                        count += 1

        results.append(str(count))

    return '\n'.join(results)
