                    for y in range(y_start + 1, y_start + size - 1):
                        for x in range(x_start + 1, x_start + size - 1):
                            if grid[y][x] != '0':
                                interior_ok = False
                                break
                        if not interior_ok:
                            break

                    if not interior_ok:
                        continue

                    # Check no foreign 1s touch the square exterior
                    exterior_ok = True
                    for y in range(max(0, y_start - 1), min(r, y_start + size)):
                        for x in range(max(0, x_start - 1), min(c, x_start + size)):
                            if grid[y][x] == '1':
                                # Check if this is outside the square
                                if (y < y_start or y >= y_start + size or 
                                    x < x_start or x >= x_start + size):
                                    exterior_ok = False
                                    break
                        if not exterior_ok:
                            break

                        # Check diagonal neighbors
                    for y in range(r):
                        for x in range(c):
                            dist_y = abs(y - y_start)
                            dist_x = abs(x - x_start)
                            if dist_y in (size, 1) or dist_x in (size, 1):
                                if grid[y][x] == '1' and (dist_y * dist_x > 0 or dist_y > 0 and dist_x > 0):
                                    exterior_ok = False
                                    break
                        if not exterior_ok:
                            break

                    if exterior_ok:
                        count += 1

        # Check diamond (rotated) squares - radius from center
        for cy in range(1, r - 1):
            for cx in range(1, c - 1):
                max_radius = min(cy, cx, r - 1 - cy, c - 1 - cx)
                for radius in range(1, max_radius + 1):
                    is_valid = True

                    # Check all boundary cells are 1
                    for y in range(r):
                        for x in range(c):
                            if abs(y - cy) + abs(x - cx) == radius:
                                if grid[y][x] != '1':
                                    is_valid = False
                                    break
                        if not is_valid:
                            break
                    if not is_valid:
                        continue

                    # Check all interior cells (radius - 1 and below) are 0
                    interior_ok = True
                    for y in range(r):
                        for x in range(c):
                            if abs(y - cy) + abs(x - cx) < radius:
                                if grid[y][x] != '0':
                                    interior_ok = False
                                    break
                        if not interior_ok:
                            break
                    if not interior_ok:
                        continue

                    # Check no foreign 1s at exact distance radius + 1
                    exterior_ok = True
                    for y in range(r):
                        for x in range(c):
                            dist = abs(y - cy) + abs(x - cx)
                            if dist == radius + 1 and grid[y][x] == '1':
                                exterior_ok = False
                                break
                        if not exterior_ok:
                            break

                    if exterior_ok:
                        count += 1

        results.append(str(count))

    return '\n'.join(results)
