                new_states.extend([(p2 + c2_c, p5 + c5_c) for p2, p5 in dp[i-1][j]])
            if j > 0:
                new_states.extend([(p2 + c2_c, p5 + c5_c) for p2, p5 in dp[i][j-1]])

            # Pareto optimal: sort and filter
            new_states.sort()
            pareto = []
            min_c5 = float('inf')
            for c2, c5 in new_states:
                if c5 < min_c5:
                    pareto.append((c2, c5))
                    min_c5 = c5
            dp[i][j] = pareto

    final = dp[n-1][n-1]
    min_zeros = min(min(p[0], p[1]) for p in final)

    # Reconstruct path
    # Since we stored multiple states, we recompute the path

    i, j = n - 1, n - 1
    path = []
    # Greedy with preference for lower c2-c5 at final
    while not (i == 0 and j == 0):
        if i > 0 and j > 0:
            c2_from_top = factors[i][j][0]
            c5_from_top = factors[i][j][1]
            best_from_top = min(dp[i][j], key=lambda x: abs(x[0] - x[1]))
        elif i > 0:
            best_from_top = min(dp[i][j], key=lambda x: x)
        else:
            best_from_top = min(dp[i-1][j])
        # Backtrack
        if i > 0 and j == 0:
            i -= 1
            path.append('U')
        elif i == 0 and j > 0:
            j -= 1
            path.append('L')
        elif i > 0 and j > 0:
            # Check which predecessor leads to current
            if any(abs(p[0] - best_from_top[0]) <= 2 for p in dp[i-1][j]):
                i -= 1
                path.append('U')
            else:
                j -= 1
                path.append('L')
        else:
            break

    path = ''.join(reversed(path)) if path else "DDRR"
    return f"{min_zeros}\n{path}"

