# Problem Analysis

This is a constraint satisfaction problem where:
- For any number x in set A, (a-x) must also be in A
- For any number x in set B, (b-x) must also be in B

The key insight is to model dependencies as a graph where each number "forces" its complement to be in the same set.

```python
import os
import sys

def solution(input_data):
    lines = input_data.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))

    # Mapping from number to its index
    num_to_idx = {val: i for i, val in enumerate(p)}

    # Build dependency graph
    # For each number, determine if it can go in set A and/or set B
    # A number x in A requires (a-x) in A (if a-x exists)
    # A number x in B requires (b-x) in B (if b-x exists)

    # We'll use union-find to track which numbers must be together in same set
    parent = list(range(n))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py

    # For each number, find its complement
    # If both x and a-x exist, they must be in the same set (either both A or both B)
    # Same for x and b-x

    # Build connected components based on complement relationships
    for i in range(n):
        x = p[i]
        a_complement = a - x
        b_complement = b - x

        if a_complement in num_to_idx:
            union(i, num_to_idx[a_complement])
            # If x is in A, a-x must be in A
            # If x is in B, a-x doesn't have to be in B (no restriction)
            # But if a-x is in A, then x must be in A

        # We need to track two separate dependency graphs (one for A, one for B)
        # But the key constraint is:
        # x in A => a-x in A
        # This means if we put x in A, all numbers connected to x via "A relations" must also be in A

    # More careful approach:
    # Build two graphs: 
    # Graph A: edges between x and a-x for all x
    # Graph B: edges between x and b-x for all x  
    # 
    # We can choose to put entire component in A or B, 
    # but a number cannot be in both if it would violate constraints

    # Actually, the key insight is:
    # - For cycle in graph A: each number in the cycle MUST be in same set (all A or all B)
    # - For cycle in graph B: each number in the cycle MUST be in same set

    # Build connectivity separately for A and B constraints
    # Track if a component is forced to be in A or forced to be in B

    # Simpler approach: try to build valid assignment using DFS
    assignment = [-1] * n  # -1 = undecided, 0 = set A, 1 = set B

    # For each number, if x is assigned to set A, then a-x must also be A (if exists)
    # If x is assigned to set B, then b-x must also be B (if exists)

    # Build A-dependency graph
    adj_a = [[] for _ in range(n)]
    for i, x in enumerate(p):
        a_comp = a - x
        if a_comp in num_to_idx:
            j = num_to_idx[a_comp]
            adj_a[i].append(j)
            adj_a[j].append(i)

    # Build B-dependency graph  
    adj_b = [[] for _ in range(n)]
    for i, x in enumerate(p):
        b_comp = b - x
        if b_comp in num_to_idx:
            j = num_to_idx[b_comp]
            adj_b[i].append(j)
            adj_b[j].append(i)

    def can_satisfy():
        # Try to find valid assignment
        # We'll process connected components

        visited = [False] * n
        assignment = [-1] * n

        def check_setB(node, forced_A):
            """Check if component needs to be in set A (forced_A=True) or set B (forced_A=False)"""
            # Propagate assignments in both graphs
            stack = [node]
            visited[node] = True

            while stack:
                u = stack.pop()

                # If already assigned, must match
                if assignment[u] != -1:
                    if forced_A and assignment[u] != 0:
                        return False
                    if not forced_A and assignment[u] != 1:
                        return False
                    continue

                if forced_A:
                    assignment[u] = 0  # Force to set A
                else:
                    assignment[u] = 1  # Force to set B

                # If in set B with a-dependent, that creates conflict unless both can be B
                # Since a-x in A is only required if we put x in A,
                # we can always put numbers in B even if they have A-dependencies

                # But if in set A with b-dependent...
                # b-x in B is only required if x in B, so no conflict

                # The real issue: number can't be both required in A and B simultaneously

                if forced_A:
                    for v in adj_b[u]:
                        if assignment[v] == -1:
                            stack.append(v)
                else:
                    for v in adj_a[u]:
                        if assignment[v] == -1:
                            stack.append(v)

            return True

        # Group into connected components in combined graph
        # Component can go to A or B

        component_groups = []
        visited = [False] * n

        for i in range(n):
            if not visited[i]:
                # Start component
                group = [i]
                stack = [i]
                visited[i] = True

                while stack:
                    u = stack.pop()
                    for v in (adj_a[u] + adj_b[u]):
                        if not visited[v]:
                            visited[v] = True
                            group.append(v)
                            stack.append(v)

                component_groups.append(group)

        # For each component, check if it can go to A and/or B
        possible = []  # (can_be_A, can_be_B) for each component

        for group in component_groups:
            # Check if component can go to A
            can_a = True

            # Check all numbers have their a-complements when in A
            for u in group:
                x = p[u]
                a_comp = a - x
                if a_comp not in num_to_idx:
                    can_a = False
                    break

                # If a-comp is not in component, can't satisfy A constraint
                # Wait, we built component group from both adj_a and adj_b
                # So if a_comp exists and is anywhere, it should be in adjacent

            possible.append((can_a, True))

        return True

    # Simpler and more direct:
    # Each number x has constraints:
    # - If x in A: (a-x) must also be in A (if a-x exists and not in B)
    # - If x in B: (b-x) must also be in B (if b-x exists and not in A)

    # Build components where numbers connected by both types of relations
    # Each component must go entirely to A OR entirely to B

    # Let's trace carefully:
    # If we put x in A:
    #   - a-x must be in A (if exists)
    #   - If we also put a-x in A, then a-a+x = a-x must be in A (trivially)
    #   - b-x has no restriction from A assignment

    # Actually: b-x must be in B IF x is in B, not if x is in A

    # So x in A means: no immediate requirement on b-x
    # x in B means: b-x must be in B

    # The only issue is: what if a component fails both A and B checks?

    def solve():
        # Mark ALL numbers that can potentially be in A
        # Number x can be in A iff (a-x) exists

        # Build sets
        p_set = set(p)
        assignment = [-1] * n  # 0 = A, 1 = B

        # Try greedy assignment
        for i in range(n):
            assignment[i] = 0  # Default to A initially

        for i in range(n):
            if assignment[i] == 0:
                # x in A
                a_comp = a - p[i]
                if a_comp not in p_set:
                    # Can't put in A, must try B
                    assignment[i] = 1
                    needed = b - p[i]
                    if needed not in p_set:
                        return "NO"

        for i in range(n):
            # Verify constraints
            if assignment[i] == 0:
                a_comp = a - p[i]
                if a_comp in p_set:
                    j = num_to_idx[a_comp]
                    if assignment[j] != 0:
                        # a-complement is in B, but x is in A - violation!
                        # Fix: put both in A
                        assignment[j] = 0
            elif assignment[i] == 1:
                b_comp = b - p[i]
                if b_comp in p_set:
                    j = num_to_idx[b_comp]
                    if assignment[j] != 1:
                        assignment[j] = 1

        # Final verification
        valid = True
        for i in range(n):
            if assignment[i] == 0:  # Set A
                a_comp = a - p[i]
                if a_comp in p_set:
                    j = num_to_idx[a_comp]
                    if assignment[j] != 0:
                        valid = False
                        break
            else:  # Set B
                b_comp = b - p[i]
                if b_comp in p_set:
                    j = num_to_idx[b_comp]
                    if assignment[j] != 1:
                        valid = False
                        break

        if valid:
            return "YES\n" + " ".join(str(assignment[i]) for i in range(n)) + " "
        else:
            return "NO"

    return solve()
