    for i in range(n):
        for j in range(m):
            if grid[i][j] != '0':
                c = grid[i][j]
                # Check all neighbors at distance exactly 1
                for di in [-1, 0, 1]:
                    for dj in [-1, 0, 1]:
                        if di == 0 and dj == 0:
                            continue
                        ni, nj = i + di, j + dj
                        if max(abs(di), abs(dj)) == 1:
                            if 0 <= ni < n and 0 <= nj < m:
                                if grid[ni][nj] != '0' and grid[ni][nj] == c:
                                    return '0'

    # Step 2: Fill in unpainted cells using a valid 4-coloring pattern
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '0':
                if i % 2 == 0:  # Even rows: colors 1, 3
                    if j % 2 == 0:
                        grid[i][j] = '1'
                    else:
                        grid[i][j] = '3'
                else:  # Odd rows: colors 2, 4
                    if j % 2 == 0:
                        grid[i][j] = '2'
                    else:
                        grid[i][j] = '4'

    # Step 3: Verify the final coloring is valid
    # (Always should be with our pattern, but good to check)
    for i in range(n):
        for j in range(m):
            c = grid[i][j]
            for di in [-1, 0, 1]:
                for dj in [-1, 0, 1]:
                    if di == 0 and dj == 0:
                        continue
