class Solution:
    def __init__(self):
        self.n = 0
        self.adj = {}
        self.p = {}  # parent array
        self.depth = {}  # depth of each node
        self.order = []  # bfs order

    def build_tree(self, n, edges):
        self.n = n
        self.adj = {i: [] for i in range(1, n + 1)}
        for u, v in edges:
            self.adj[u].append(v)
            self.adj[v].append(u)

    def get_lca_path(self, u, v):
        """Get path between u and v via LCA"""
        def get_path_to_root(node, parent):
            path = []
            while node != 0:
                path.append(node)
                node = self.p[node]
            return path

        if u == v:
            return [u, v]

        path_u = get_path_to_root(u, None)
        path_v = get_path_to_root(v, None)

        lca = path_u[-1] if not path_v else None
        for i in range(len(path_u) - 1, -1, -1):
            if path_u[i] in path_v:
                lca = path_u[i]
                break

        if lca is None:
            return [u, v]

        path_u = [node for node in path_u if node >= lca]
        path_v = [node for node in path_v if node >= lca]

        return path_u + path_v[::-1][1:]

    def get_path_vertices(self, u, v):
        """Get all vertices on simple path from u to v"""
